changeSet.sql:
ALTER TABLE lock ADD CONSTRAINT lock_device_type_check CHECK (device_type IN ('SMART_LOCK', 'OPENER'));
ALTER TABLE lock ADD CONSTRAINT lock_entrance_not_itself_check CHECK (entrance_lock_id <> id);

-- Locks are only deleted with their owner; SET NULL on one column of a composite key, as in 006-lock.
ALTER TABLE lock ADD CONSTRAINT lock_entrance_fkey
    FOREIGN KEY (owner_id, entrance_lock_id) REFERENCES lock (owner_id, id)
    ON DELETE SET NULL (entrance_lock_id);

ALTER TABLE access_event ADD CONSTRAINT access_event_entrance_fkey
    FOREIGN KEY (owner_id, entrance_lock_id) REFERENCES lock (owner_id, id)
    ON DELETE CASCADE;
